-- Preserve operator customizations while replacing the obsolete instruction.
UPDATE public.agent_configuration_catalog
SET definition=jsonb_set(definition, '{default}', to_jsonb(replace(definition->>'default', 'Quando status matched e availability available, informe o modelo tecnicamente compativel e a falta de preco valido; nao recomende por zero, nao confirme o orcamento e nao exija repetir a mesma consulta sem nova evidencia.', 'Em buscas por recomendação, somente commercial_data.products contém opções aprovadas. technical_evidence registra também candidatos rejeitados e não autoriza oferecê-los ou selecioná-los. Se não houver produto aprovado, informe que a consulta não confirmou todos os critérios; não destaque um candidato sem preço válido ou indisponível. Em consulta explícita sobre um produto específico, explique fielmente a falta de preço ou disponibilidade sem confirmar orçamento ou possibilidade de compra.'))), updated_at=now()
WHERE key IN ('message.critique_availability_evidence','message.catalog_retrieval_response_contract');
